module.exports = create;

function create(major, minor, build) {
  return {
    $: {
      major,
      minor,
      build,
      //  uid: uid
    },
    $class: { name: 'com.alipay.config.common.protocol.NVersionElement',
      serialVersionUID: '1',
      flags: 2,
      fields:
      [{ type: 'I', name: 'build' },
        { type: 'S', name: 'major' },
        { type: 'S', name: 'minor' }],
      superClass: null },
  };
}

module.exports.CURRENT = create(1, 2, 0);
